commands.graphs.ps1:
param([ValidateSet('before','after')][string]$Phase)
$ErrorActionPreference='Stop'
Set-Location O:/repos.hobby/ntvdm64
try {
 $node='C:/Program Files/WindowsApps/OpenAI.CodexPrimaryRuntime.v26-1112-611-0_26.1112.611.0_x64__3k8sg7r9htsxt/dependencies/node/bin/node.exe'
 $ninja='C:/Users/neko/AppData/Local/Microsoft/WinGet/Packages/BrechtSanders.WinLibs.POSIX.MSVCRT_Microsoft.Winget.Source_8wekyb3d8bbwe/mingw64/bin/ninja.exe'
 $rows=@()
 foreach($arch in @('x86')) {
  $root="O:/repos.hobby/ntvdm64/build/.ninja/t483-s5-p119-$arch"
  & tools/build/New-T310OriginalSoftpcNinja.ps1 -Architecture $arch -RepositoryRoot O:/repos.hobby/ntvdm64 -BuildRoot $root -NodeExecutable $node -NinjaExecutable $ninja
  if($LASTEXITCODE){throw "Generator $arch failed"}
  $hash=(Get-FileHash "$root/build.ninja").Hash
  if($Phase -eq 'before'){Copy-Item "$root/build.ninja" "build/t483-s5-p119/$arch-before.ninja"}
  else {if($hash -ne (Get-FileHash "build/t483-s5-p119/$arch-before.ninja").Hash){throw "$arch graph changed"}}
  $graph=Get-Content "$root/build.ninja" -Raw
  if($graph -match '(?i)(?<![-a-z])monitor\.lib|[/\\]tsa\.c'){throw 'Excluded provider selected'}
  $rows+=@{architecture=$arch;graph_sha256=$hash;excluded_provider_absent=$true}
 }
 $rows|ConvertTo-Json|Set-Content "build/t483-s5-p119/$Phase-graphs.json"
 0|Set-Content "build/t483-s5-p119/$Phase.exit"
}catch {$_|Out-String|Write-Output;1|Set-Content "build/t483-s5-p119/$Phase.exit";exit 1}

commands.restore-validate.ps1:
$ErrorActionPreference='Stop'
Set-Location O:/repos.hobby/ntvdm64
try {
 $p=Get-Process -Id 5264 -ErrorAction SilentlyContinue
 if($p){Wait-Process -Id 5264 -Timeout 300}
 if((Get-Content build/t483-s5-p119/before.exit).Trim() -ne '0'){throw 'Before graph did not pass'}
 & python build/t483-s5-p119/restore.py
 if($LASTEXITCODE){throw 'Original restoration failed'}
 & "$PSScriptRoot/graphs.ps1" -Phase after
 if($LASTEXITCODE){throw 'After graph failed'}
 $tokens=$null;$errors=$null
 $ast=[Management.Automation.Language.Parser]::ParseFile((Resolve-Path tools/build/New-T310OriginalSoftpcNinja.ps1),[ref]$tokens,[ref]$errors)
 if($errors.Count){throw 'Generator parser errors'}
 $fn=$ast.Find({param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Get-OriginalSources'},$true)
 . ([scriptblock]::Create($fn.Extent.Text))
 $before=@(Get-OriginalSources build/t483-s5-p119/suballoc-before)
 $after=@(Get-OriginalSources build/t483-s5-p119/suballoc-after)
 if((Compare-Object $before $after -SyncWindow 0) -or $after.Count -ne 1 -or $after[0] -ne 'suballoc.c'){throw 'Suballoc selection changed'}
 @{selected=$after;equal=$true;provider='real Get-OriginalSources AST'}|ConvertTo-Json|Set-Content build/t483-s5-p119/parser.json
 0|Set-Content build/t483-s5-p119/validation.exit
} catch {$_|Out-String|Write-Output;1|Set-Content build/t483-s5-p119/validation.exit;exit 1}
